#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int h;
    int idx;
} Rect;

int cmp(const void *a, const void *b) {
    const Rect *ra = (const Rect *)a;
    const Rect *rb = (const Rect *)b;
    if (ra->h != rb->h) return rb->h - ra->h;
    return ra->idx - rb->idx;
}

int main() {
    int N;
    scanf("%d", &N);

    Rect *rects = (Rect *)malloc(N * sizeof(Rect));
    for (int i = 0; i < N; i++) {
        scanf("%d", &rects[i].h);
        rects[i].idx = i + 1;
    }

    qsort(rects, N, sizeof(Rect), cmp);

    char *active = (char *)calloc(N + 2, sizeof(char));
    int runs = 0;
    int max_runs = 0;

    int i = 0;
    while (i < N) {
        int h = rects[i].h;
        while (i < N && rects[i].h == h) {
            int pos = rects[i].idx;
            active[pos] = 1;

            int left = active[pos - 1];
            int right = active[pos + 1];

            if (!left && !right) {
                runs++;
            } else if (left && right) {
                runs--;
            }

            i++;
        }

        if (runs > max_runs) {
            max_runs = runs;
        }
    }

    printf("%d\n", max_runs + 1);

    free(rects);
    free(active);
    return 0;
}
